import subprocess,os
from pathlib import Path
root=Path('/nexus/Dev/OpenCog/NL2PLN_Project/PeTTaChainer');b=Path('/tmp/stationops-depth-results')
for seed,budget in [(7,600),(11,300),(23,300)]:
 for label,repo in ([('control',root),('shorter',Path('/tmp/stationops-depth'))] if seed!=11 else [('shorter',Path('/tmp/stationops-depth')),('control',root)]):
  name=f'{label}-{seed}'
  with (b/(name+'.log')).open('w') as log:
   try:
    p=subprocess.run([str(root/'.venv/bin/python'),str(b/'benchmark.py'),'--repository',str(repo),'--chainergame',str(root/'../../ChainerGame'),'--petta',str(root/'third_party/petta'),'--json-out',str(b/(name+'.json')),'--seed',str(seed),'--budget',str(budget)],stdout=log,stderr=subprocess.STDOUT,timeout=240,env={**os.environ,'PYTHONDONTWRITEBYTECODE':'1'})
    print(name,p.returncode,flush=True)
   except subprocess.TimeoutExpired:print(name,'TIMEOUT',flush=True)

